contracts/FallbackExecutor.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {IUniswapV2Router02} from "./interfaces/IUniswapV2Router.sol";
import {IUniswapV2Factory} from "./interfaces/IUniswapV2Factory.sol";
import {IUniswapV2Pair} from "./interfaces/IUniswapV2Pair.sol";
import {IGradientRegistry} from "./interfaces/IGradientRegistry.sol";

/**
 * @title FallbackExecutor
 * @notice Handles fallback execution of trades through external AMMs
 * @dev Integrates with Uniswap V2 and can be extended to support other DEXes
 */
contract FallbackExecutor is ReentrancyGuard, Ownable {
    using SafeERC20 for IERC20;

    // Registry contract for checking blocked tokens
    IGradientRegistry public immutable gradientRegistry;

    // DEX configurations
    struct DEXConfig {
        address router;
        address factory;
        bool isActive;
        uint256 priority; // Lower number = higher priority
    }

    // State variables
    mapping(address => DEXConfig) public dexes;
    address[] public activeDEXes;
    mapping(address => uint256) public dexIndex; // Track DEX position in array for O(1) removal

    uint256 public maxDEXs = 5;
    uint256 public constant MAX_DEADLINE = 300; // 5 minutes
    uint256 public minLiquidityThreshold = 10 ether; // Minimum liquidity in ETH equivalent

    // Events
    event DEXAdded(address indexed dex, address router, address factory);
    event DEXRemoved(address indexed dex);
    event MinLiquidityThresholdUpdated(
        uint256 oldThreshold,
        uint256 newThreshold
    );
    event TradeExecuted(
        address indexed token,
        address indexed dex,
        uint256 amountIn,
        uint256 amountOut,
        bool isBuy
    );

    // Modifiers
    modifier onlyOrderbook() {
        require(
            msg.sender == gradientRegistry.orderbook(),
            "FallbackExecutor: Only orderbook can call"
        );
        _;
    }

    constructor(IGradientRegistry _gradientRegistry) Ownable(msg.sender) {
        gradientRegistry = _gradientRegistry;
    }

    /**
     * @notice Add a new DEX to the fallback system
     * @param dex The DEX address
     * @param router The DEX's router contract
     * @param priority Priority level (lower = higher priority)
     */
    function addDEX(
        address dex,
        address router,
        uint256 priority
    ) external onlyOwner {
        require(activeDEXes.length < maxDEXs, "Max DEXs reached");
        require(dex != address(0), "Invalid DEX");
        require(router != address(0), "Invalid router");
        require(!dexes[dex].isActive, "DEX already exists");

        address factory = IUniswapV2Router02(router).factory();
        dexes[dex] = DEXConfig({
            router: router,
            factory: factory,
            isActive: true,
            priority: priority
        });

        activeDEXes.push(dex);
        dexIndex[dex] = activeDEXes.length - 1; // Set initial index
        _sortDEXesByPriority();

        emit DEXAdded(dex, router, factory);
    }

    /**
     * @notice Remove a DEX from the fallback system
     * @param dex The DEX to remove
     */
    function removeDEX(address dex) external onlyOwner {
        require(dexes[dex].isActive, "DEX not found");

        uint256 lastDEXIndex = activeDEXes.length - 1;
        address lastDEX = activeDEXes[lastDEXIndex];

        // Swap the element to remove with the last element
        activeDEXes[dexIndex[dex]] = lastDEX;
        dexIndex[lastDEX] = dexIndex[dex];

        // Remove the last element
        activeDEXes.pop();
        delete dexIndex[dex];

        dexes[dex].isActive = false;

        emit DEXRemoved(dex);
    }

    /**
     * @notice Set the minimum liquidity threshold to protect against price manipulation
     * @param newThreshold The new minimum liquidity threshold in ETH equivalent
     * @dev Only callable by contract owner
     * @dev Higher thresholds provide better protection but may exclude more DEXes
     */
    function setMinLiquidityThreshold(uint256 newThreshold) external onlyOwner {
        require(newThreshold > 0, "Threshold must be greater than 0");
        require(newThreshold <= 1000 ether, "Threshold too high"); // Reasonable upper limit

        uint256 oldThreshold = minLiquidityThreshold;
        minLiquidityThreshold = newThreshold;

        emit MinLiquidityThresholdUpdated(oldThreshold, newThreshold);
    }

    /**
     * @notice Execute a trade through the best available DEX
     * @param token The token to trade
     * @param amount The amount to trade
     * @param minAmountOut Minimum amount to receive
     * @param isBuy Whether this is a buy or sell order
     * @return amountOut The actual amount received from the trade
     * @dev Only callable by the orderbook contract to prevent fee bypass
     */
    function executeTrade(
        address token,
        uint256 amount,
        uint256 minAmountOut,
        bool isBuy
    ) external payable onlyOrderbook nonReentrant returns (uint256 amountOut) {
        require(token != address(0), "Invalid token");
        require(amount > 0, "Amount must be greater than 0");
        require(minAmountOut > 0, "Invalid minAmountOut");
        require(!gradientRegistry.blockedTokens(token), "Token is blocked");

        // For buy orders, require ETH to be sent
        if (isBuy) {
            require(msg.value >= amount, "Insufficient ETH sent for buy order");
        }

        // Get the best DEX for this trade
        address bestDEX = _getBestDEX(token, amount, isBuy);
        require(bestDEX != address(0), "No suitable DEX found");

        DEXConfig storage dexConfig = dexes[bestDEX];
        IUniswapV2Router02 router = IUniswapV2Router02(dexConfig.router);

        // Prepare path
        address[] memory path = new address[](2);
        if (isBuy) {
            path[0] = router.WETH(); // WETH
            path[1] = token;
        } else {
            path[0] = token;
            path[1] = router.WETH(); // WETH
        }

        // Execute trade
        if (isBuy) {
            // Buy tokens with ETH
            uint256 balanceBefore = IERC20(token).balanceOf(msg.sender);

            router.swapExactETHForTokensSupportingFeeOnTransferTokens{
                value: amount
            }(minAmountOut, path, msg.sender, block.timestamp + MAX_DEADLINE);

            uint256 balanceAfter = IERC20(token).balanceOf(msg.sender);
            amountOut = balanceAfter - balanceBefore;

            // Validate slippage protection
            require(amountOut >= minAmountOut, "Insufficient output amount");
        } else {
            // Sell tokens for ETH
            uint256 balanceBefore = address(this).balance;
            IERC20(token).safeTransferFrom(msg.sender, address(this), amount);

            // Safe approval pattern
            _safeApprove(token, dexConfig.router, amount);

            router.swapExactTokensForETHSupportingFeeOnTransferTokens(
                amount,
                minAmountOut,
                path,
                address(this),
                block.timestamp + MAX_DEADLINE
            );

            uint256 balanceAfter = address(this).balance;
            amountOut = balanceAfter - balanceBefore;

            // Validate slippage protection
            require(amountOut >= minAmountOut, "Insufficient output amount");

            // Transfer ETH to caller
            (bool success, ) = msg.sender.call{value: amountOut}("");
            require(success, "ETH transfer failed");
        }

        emit TradeExecuted(token, bestDEX, amount, amountOut, isBuy);
        return amountOut;
    }

    /**
     * @notice Get the best DEX for a trade
     * @param token The token to trade
     * @param amount The amount to trade
     * @param isBuy Whether this is a buy or sell order
     * @return The address of the best DEX
     */
    function _getBestDEX(
        address token,
        uint256 amount,
        bool isBuy
    ) internal view returns (address) {
        // Try all active DEXes in priority order
        for (uint256 i = 0; i < activeDEXes.length; i++) {
            address dex = activeDEXes[i];
            if (_isDEXSuitable(dex, token, amount, isBuy)) {
                return dex;
            }
        }

        return address(0);
    }

    /**
     * @notice Get all active DEXes in priority order
     * @return Array of DEX addresses sorted by priority (lowest first)
     */
    function getActiveDEXes() external view returns (address[] memory) {
        return activeDEXes;
    }

    /**
     * @notice Get DEX configuration by address
     * @param dex The DEX address
     * @return DEXConfig struct containing router, factory, isActive, and priority
     */
    function getDEXConfig(
        address dex
    ) external view returns (DEXConfig memory) {
        return dexes[dex];
    }

    /**
     * @notice Check if a DEX is suitable for a trade
     * @param dex The DEX to check
     * @param token The token to trade
     * @param amount The amount to trade
     * @param isBuy Whether this is a buy or sell order
     */
    function _isDEXSuitable(
        address dex,
        address token,
        uint256 amount,
        bool isBuy
    ) internal view returns (bool) {
        DEXConfig storage dexConfig = dexes[dex];
        if (!dexConfig.isActive) return false;

        // Get WETH address from router
        IUniswapV2Router02 router = IUniswapV2Router02(dexConfig.router);
        address weth = router.WETH();

        // Check if the pair exists
        address pair = IUniswapV2Factory(dexConfig.factory).getPair(
            token,
            weth
        );
        if (pair == address(0)) return false;

        // Check liquidity
        (uint112 reserve0, uint112 reserve1, ) = IUniswapV2Pair(pair)
            .getReserves();
        uint256 tokenReserve = token < weth ? reserve0 : reserve1;
        uint256 ethReserve = token < weth ? reserve1 : reserve0;

        // Check minimum liquidity threshold (protects against flash loan attacks)
        if (ethReserve < minLiquidityThreshold) {
            return false;
        }

        // Ensure sufficient liquidity with safety margin for the specific trade
        if (isBuy) {
            return ethReserve >= (amount * 11) / 10; // 10% safety margin
        } else {
            return tokenReserve >= (amount * 11) / 10; // 10% safety margin
        }
    }

    /**
     * @notice Safe approval pattern that resets approval to 0 first
     * @param token The token to approve
     * @param spender The spender address
     * @param amount The amount to approve
     */
    function _safeApprove(
        address token,
        address spender,
        uint256 amount
    ) internal {
        IERC20(token).approve(spender, 0); // Reset approval
        IERC20(token).approve(spender, amount); // Set new approval
    }

    /**
     * @notice Sort DEXes by priority
     */
    function _sortDEXesByPriority() internal {
        // Insertion sort - more efficient than bubble sort for small arrays
        for (uint256 i = 1; i < activeDEXes.length; i++) {
            address currentDEX = activeDEXes[i];
            uint256 currentPriority = dexes[currentDEX].priority;
            uint256 j = i;

            // Move elements that are greater than current one position ahead
            while (
                j > 0 && dexes[activeDEXes[j - 1]].priority > currentPriority
            ) {
                address movedDEX = activeDEXes[j - 1];
                activeDEXes[j] = movedDEX;
                dexIndex[movedDEX] = j; // Update index for the moved DEX
                j--;
            }

            // Place current element in correct position
            activeDEXes[j] = currentDEX;
            dexIndex[currentDEX] = j; // Update index mapping
        }
    }

    /**
     * @notice Emergency withdraw function for owner to withdraw all ETH and tokens
     * @param tokens Array of token addresses to withdraw
     * @dev Only callable by contract owner
     * @dev Use this function ONLY in emergency situations such as:
     *      - Contract vulnerability or exploit detected
     *      - Critical bug in liquidity management logic
     *      - Migration to new contract version
     *      - Recovery of stuck or locked funds
     *      - Security incident requiring immediate asset protection
     * @dev This function bypasses all normal withdrawal logic and directly transfers assets
     */
    function emergencyWithdraw(address[] calldata tokens) external onlyOwner {
        // Withdraw all ETH
        uint256 ethBalance = address(this).balance;
        if (ethBalance > 0) {
            (bool success, ) = owner().call{value: ethBalance}("");
            require(success, "ETH withdrawal failed");
        }

        // Withdraw all specified tokens
        for (uint256 i = 0; i < tokens.length; i++) {
            address token = tokens[i];
            if (token != address(0)) {
                uint256 tokenBalance = IERC20(token).balanceOf(address(this));
                if (tokenBalance > 0) {
                    IERC20(token).safeTransfer(owner(), tokenBalance);
                }
            }
        }
    }

    /**
     * @notice Emergency withdraw function for owner to withdraw all ETH
     * @dev Only callable by contract owner
     * @dev Use this function ONLY in emergency situations such as:
     *      - Contract vulnerability or exploit detected
     *      - Critical bug in liquidity management logic
     *      - Migration to new contract version
     *      - Recovery of stuck or locked funds
     *      - Security incident requiring immediate asset protection
     * @dev This function bypasses all normal withdrawal logic and directly transfers ETH
     */
    function emergencyWithdrawETH() external onlyOwner {
        uint256 balance = address(this).balance;
        if (balance > 0) {
            (bool success, ) = owner().call{value: balance}("");
            require(success, "ETH withdrawal failed");
        }
    }

    receive() external payable {}
}

contracts/GradientMarketMakerPool.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {IERC20Metadata} from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {IGradientRegistry} from "./interfaces/IGradientRegistry.sol";
import {IGradientMarketMakerPool} from "./interfaces/IGradientMarketMakerPool.sol";
import {IUniswapV2Pair} from "./interfaces/IUniswapV2Pair.sol";
import {IUniswapV2Router02} from "./interfaces/IUniswapV2Router.sol";
import {IUniswapV2Factory} from "./interfaces/IUniswapV2Factory.sol";

contract GradientMarketMakerPool is
    Ownable,
    ReentrancyGuard,
    IGradientMarketMakerPool
{
    using SafeERC20 for IERC20;
    IGradientRegistry public gradientRegistry;

    // Epoch-based storage
    // token => currentEpoch (for ETH pool)
    mapping(address => uint256) public currentETHEpochs;
    // token => currentEpoch (for token pool)
    mapping(address => uint256) public currentTokenEpochs;

    // token => epoch => ETHPoolInfo
    mapping(address => mapping(uint256 => ETHPoolInfo)) public ethPools;
    // token => epoch => TokenPoolInfo
    mapping(address => mapping(uint256 => TokenPoolInfo)) public tokenPools;

    // User positions in each epoch
    // token => user => epoch => ETHProvider
    mapping(address => mapping(address => mapping(uint256 => ETHProvider)))
        public ethProviders;
    // token => user => epoch => TokenProvider
    mapping(address => mapping(address => mapping(uint256 => TokenProvider)))
        public tokenProviders;

    // Track user's participated epochs
    // token => user => ETH epochIds[]
    mapping(address => mapping(address => uint256[]))
        public userParticipatedETHEpochs;
    // token => user => token epochIds[]
    mapping(address => mapping(address => uint256[]))
        public userParticipatedTokenEpochs;

    uint256 public constant SCALE = 1e18;

    // Configurable minimum liquidity requirements
    uint256 public minLiquidity = 1e15; // 0.001 ETH minimum (default)
    uint256 public minTokenLiquidity = 1e15; // 0.001 tokens minimum (default)

    // Track overall totals across all pools
    uint256 public totalEthAdded; // Total ETH added across all pools
    uint256 public totalEthRemoved; // Total ETH removed across all pools

    mapping(address => uint256) public totalTokensAdded; // Total tokens added across all pools (per token)
    mapping(address => uint256) public totalTokensRemoved; // Total tokens removed across all pools (per token)

    // Gas limit protection for batch operations
    uint256 public constant MAX_BATCH_SIZE = 20; // Maximum items per batch
    uint256 public constant GAS_LIMIT_PER_ITEM = 50000; // Estimated gas per removal operation
    uint256 public constant GAS_BUFFER = 100000; // Gas buffer for safety

    // Epoch manipulation protection
    // token => last ETH epoch increment timestamp
    mapping(address => uint256) public lastETHEpochIncrementTime;
    // token => last token epoch increment timestamp
    mapping(address => uint256) public lastTokenEpochIncrementTime;

    // Minimum time between epoch increments (cooldown period)
    uint256 public epochCooldownPeriod = 1 hours; // Default: 1 hour cooldown

    // Minimum liquidity thresholds for epoch progression
    uint256 public minLiquidityForEpochProgression = 1e16; // 0.01 ETH minimum

    event BatchRemovalCompleted(
        address indexed user,
        address indexed token,
        uint256 totalProcessed
    );

    modifier isNotBlocked(address token) {
        require(!gradientRegistry.blockedTokens(token), "Token is blocked");
        _;
    }

    modifier onlyRewardDistributor() {
        require(
            gradientRegistry.isRewardDistributor(msg.sender),
            "Only reward distributor can call this function"
        );
        _;
    }

    modifier onlyOrderbook() {
        require(
            msg.sender == gradientRegistry.orderbook(),
            "Only orderbook can call this function"
        );
        _;
    }

    constructor(IGradientRegistry _gradientRegistry) Ownable(msg.sender) {
        gradientRegistry = _gradientRegistry;
    }

    /**
     * @notice Receive ETH for reward distribution
     */
    receive() external payable {}

    // =============================== INTERNAL FUNCTIONS ===============================

    /**
     * @notice Calculate LP shares using a more secure formula to prevent precision loss
     * @param amount Amount being deposited
     * @param totalAmount Total amount in pool
     * @param totalShares Total shares in pool
     * @return sharesToMint Number of shares to mint
     */
    function _calculateLPShares(
        uint256 amount,
        uint256 totalAmount,
        uint256 totalShares
    ) internal pure returns (uint256 sharesToMint) {
        require(amount > 0, "Amount must be greater than 0");

        if (totalShares == 0) {
            // First liquidity provider gets shares equal to their contribution
            return amount;
        }

        // Calculate shares proportionally
        sharesToMint = (amount * totalShares) / totalAmount;

        // Ensure minimum share requirement to prevent dust attacks
        require(sharesToMint > 0, "Insufficient shares to mint");

        return sharesToMint;
    }

    /**
     * @notice Updates ETH pool rewards before modifying state
     * @param token Address of the token for the pool
     * @param epoch Epoch to update
     * @param ethAmount Amount of ETH to distribute as rewards
     */
    function _updateETHPool(
        address token,
        uint256 epoch,
        uint256 ethAmount
    ) internal {
        require(ethAmount > 0, "ETH amount must be greater than 0");
        require(token != address(0), "Invalid token address");
        ETHPoolInfo storage pool = ethPools[token][epoch];

        if (pool.totalLPShares == 0) return;

        uint256 newAccRewardPerShare = pool.accRewardPerShare +
            ((ethAmount * SCALE) / pool.totalLPShares);
        require(
            newAccRewardPerShare >= pool.accRewardPerShare,
            "Overflow in reward calculation"
        );

        pool.accRewardPerShare = newAccRewardPerShare;
        pool.rewardBalance += ethAmount;
    }

    /**
     * @notice Updates Token pool rewards before modifying state
     * @param token Address of the token for the pool
     * @param ethAmount Amount of ETH to distribute as rewards
     */
    function _updateTokenPool(
        address token,
        uint256 epoch,
        uint256 ethAmount
    ) internal {
        require(ethAmount > 0, "ETH amount must be greater than 0");
        require(token != address(0), "Invalid token address");
        TokenPoolInfo storage pool = tokenPools[token][epoch];

        if (pool.totalLPShares == 0) return;

        uint256 newAccRewardPerShare = pool.accRewardPerShare +
            ((ethAmount * SCALE) / pool.totalLPShares);
        require(
            newAccRewardPerShare >= pool.accRewardPerShare,
            "Overflow in reward calculation"
        );

        pool.accRewardPerShare = newAccRewardPerShare;
        pool.rewardBalance += ethAmount;
    }

    /**
     * @notice Updates ETH pool token rewards before modifying state
     * @param token Address of the token for the pool
     * @param tokenAmount Amount of tokens to distribute as rewards
     */
    function _updateETHPoolTokenRewards(
        address token,
        uint256 tokenAmount
    ) internal {
        require(tokenAmount > 0, "Token amount must be greater than 0");
        require(token != address(0), "Invalid token address");
        ETHPoolInfo storage pool = ethPools[token][currentETHEpochs[token]];

        if (pool.totalLPShares == 0) return;

        uint256 newAccTokenRewardPerShare = pool.accTokenRewardPerShare +
            ((tokenAmount * SCALE) / pool.totalLPShares);
        require(
            newAccTokenRewardPerShare >= pool.accTokenRewardPerShare,
            "Overflow in token reward calculation"
        );

        pool.accTokenRewardPerShare = newAccTokenRewardPerShare;
        pool.tokenRewardBalance += tokenAmount;
    }

    /**
     * @notice Updates Token pool ETH rewards before modifying state
     * @param token Address of the token for the pool
     * @param ethAmount Amount of ETH to distribute as rewards
     */
    function _updateTokenPoolETHRewards(
        address token,
        uint256 ethAmount
    ) internal {
        require(ethAmount > 0, "ETH amount must be greater than 0");
        require(token != address(0), "Invalid token address");
        TokenPoolInfo storage pool = tokenPools[token][
            currentTokenEpochs[token]
        ];

        if (pool.totalLPShares == 0) return;

        uint256 newAccETHRewardPerShare = pool.accETHRewardPerShare +
            ((ethAmount * SCALE) / pool.totalLPShares);
        require(
            newAccETHRewardPerShare >= pool.accETHRewardPerShare,
            "Overflow in ETH reward calculation"
        );

        pool.accETHRewardPerShare = newAccETHRewardPerShare;
        pool.ethRewardBalance += ethAmount;
    }

    /**
     * @notice Check if ETH pool is empty and finalize ETH epoch if needed
     * @param token Address of the token
     */
    function _checkAndIncrementETHEpoch(address token) internal {
        ETHPoolInfo storage ethPool = ethPools[token][currentETHEpochs[token]];

        // Finalize ETH epoch when pool becomes empty (don't increment yet)
        if (ethPool.totalETH == 0 && !ethPool.finalized) {
            ethPool.finalized = true;
            lastETHEpochIncrementTime[token] = block.timestamp;
            emit EpochFinalized(token, currentETHEpochs[token], true);
        }
    }

    /**
     * @notice Check if token pool is empty and finalize token epoch if needed
     * @param token Address of the token
     */
    function _checkAndIncrementTokenEpoch(address token) internal {
        TokenPoolInfo storage tokenPool = tokenPools[token][
            currentTokenEpochs[token]
        ];

        // Finalize token epoch when pool becomes empty (don't increment yet)
        if (tokenPool.totalTokens == 0 && !tokenPool.finalized) {
            tokenPool.finalized = true;
            lastTokenEpochIncrementTime[token] = block.timestamp;
            emit EpochFinalized(token, currentTokenEpochs[token], false);
        }
    }

    /**
     * @notice Calculate withdrawal amount with proper validation
     * @param sharesToBurn Number of shares being burned
     * @param totalAmount Total amount in pool
     * @param totalShares Total shares in pool
     * @return withdrawalAmount Amount to withdraw
     */
    function _calculateWithdrawalAmount(
        uint256 sharesToBurn,
        uint256 totalAmount,
        uint256 totalShares
    ) internal pure returns (uint256 withdrawalAmount) {
        require(sharesToBurn > 0, "Shares to burn must be greater than 0");
        require(totalShares > 0, "Total shares must be greater than 0");

        // Calculate withdrawal amount proportionally
        withdrawalAmount = (sharesToBurn * totalAmount) / totalShares;

        require(
            withdrawalAmount <= totalAmount,
            "Withdrawal amount exceeds pool balance"
        );

        return withdrawalAmount;
    }

    /**
     * @notice Add user to participated epochs if not already present
     * @param token Address of the token
     * @param user Address of the user
     * @param epochId Epoch ID to add
     * @param isETHEpoch Whether this is an ETH epoch (true) or token epoch (false)
     */
    function _addUserToParticipatedEpochs(
        address token,
        address user,
        uint256 epochId,
        bool isETHEpoch
    ) internal {
        uint256[] storage epochs = isETHEpoch
            ? userParticipatedETHEpochs[token][user]
            : userParticipatedTokenEpochs[token][user];
        bool found = false;

        for (uint256 i = 0; i < epochs.length; i++) {
            if (epochs[i] == epochId) {
                found = true;
                break;
            }
        }

        if (!found) {
            epochs.push(epochId);
        }
    }

    // =============================== PUBLIC FUNCTIONS ===============================

    /**
     * @notice Add liquidity to the pool
     * @param token Address of the token to provide liquidity for
     * @param tokenAmount Amount of tokens to deposit
     */
    function addLiquidity(
        address token,
        uint256 tokenAmount
    ) external payable isNotBlocked(token) nonReentrant {
        require(msg.value >= minLiquidity, "ETH amount below minimum");
        require(tokenAmount >= minTokenLiquidity, "Token amount below minimum");
        require(token != address(0), "Invalid token address");

        _addETHLiquidity(token, msg.value);
        _addTokenLiquidity(token, tokenAmount);
    }

    /**
     * @notice Add ETH liquidity to the pool
     * @param token Address of the token to provide ETH liquidity for
     * @dev Requires ETH to be sent with the transaction
     */
    function addETHLiquidity(
        address token
    ) public payable isNotBlocked(token) nonReentrant {
        require(msg.value >= minLiquidity, "ETH amount below minimum");
        require(token != address(0), "Invalid token address");

        _addETHLiquidity(token, msg.value);
    }

    /**
     * @notice Add ETH liquidity to the pool
     * @param token Address of the token to provide ETH liquidity for
     * @param ethAmount Amount of ETH to deposit
     */
    function _addETHLiquidity(address token, uint256 ethAmount) internal {
        // Check if current epoch is finalized and apply cooldown restrictions
        if (ethPools[token][currentETHEpochs[token]].finalized) {
            // Check cooldown period for finalized epochs
            require(
                block.timestamp >=
                    lastETHEpochIncrementTime[token] + epochCooldownPeriod,
                "ETH epoch cooldown period not met"
            );

            // Check minimum liquidity threshold for new epochs
            require(
                ethAmount >= minLiquidityForEpochProgression,
                "Insufficient liquidity for new epoch"
            );

            // Increment to next epoch since cooldown period has passed
            currentETHEpochs[token]++;
        }
        ETHPoolInfo storage pool = ethPools[token][currentETHEpochs[token]];

        if (pool.uniswapPair == address(0)) {
            pool.uniswapPair = getPairAddress(token);
        }
        require(pool.uniswapPair != address(0), "Pair does not exist");

        ETHProvider storage provider = ethProviders[token][msg.sender][
            currentETHEpochs[token]
        ];

        // Add user to participated epochs
        _addUserToParticipatedEpochs(
            token,
            msg.sender,
            currentETHEpochs[token],
            true
        );

        // Calculate pending ETH rewards before update
        if (provider.lpShares > 0) {
            uint256 pendingEth = (provider.lpShares * pool.accRewardPerShare) /
                SCALE -
                provider.rewardDebt;
            provider.pendingReward += pendingEth;

            // Calculate pending token rewards before update
            uint256 pendingTokens = (provider.lpShares *
                pool.accTokenRewardPerShare) /
                SCALE -
                provider.tokenRewardDebt;
            provider.pendingTokenReward += pendingTokens;
        }

        // Calculate LP shares to mint
        uint256 lpSharesToMint = _calculateLPShares(
            ethAmount,
            pool.accountedEth,
            pool.totalLPShares
        );

        provider.lpShares += lpSharesToMint;
        provider.ethAmount += ethAmount;
        provider.rewardDebt =
            (provider.lpShares * pool.accRewardPerShare) /
            SCALE;
        provider.tokenRewardDebt =
            (provider.lpShares * pool.accTokenRewardPerShare) /
            SCALE;

        pool.totalETH += ethAmount;
        pool.accountedEth += ethAmount;
        pool.totalLPShares += lpSharesToMint;

        // Track total ETH added by LPs
        totalEthAdded += ethAmount;

        emit ETHLiquidityDeposited(
            msg.sender,
            token,
            ethAmount,
            lpSharesToMint
        );
    }

    /**
     * @notice Add token liquidity to the pool
     * @param token Address of the token to provide liquidity for
     * @param tokenAmount Amount of tokens to deposit
     */
    function addTokenLiquidity(
        address token,
        uint256 tokenAmount
    ) public isNotBlocked(token) nonReentrant {
        require(tokenAmount >= minTokenLiquidity, "Token amount below minimum");
        require(token != address(0), "Invalid token address");

        _addTokenLiquidity(token, tokenAmount);
    }

    /**
     * @notice Add token liquidity to the pool
     * @param token Address of the token to provide liquidity for
     * @param tokenAmount Amount of tokens to deposit
     */
    function _addTokenLiquidity(address token, uint256 tokenAmount) internal {
        TokenPoolInfo storage pool = tokenPools[token][
            currentTokenEpochs[token]
        ];

        // Check if current epoch is finalized and apply cooldown restrictions
        if (pool.finalized) {
            // Check cooldown period for finalized epochs
            require(
                block.timestamp >=
                    lastTokenEpochIncrementTime[token] + epochCooldownPeriod,
                "Token epoch cooldown period not met"
            );

            // Check minimum liquidity threshold for new epochs (using ETH equivalent)
            uint256 tokenEthEquivalent = _calculateTokenEthEquivalent(
                token,
                tokenAmount
            );
            require(
                tokenEthEquivalent >= minLiquidityForEpochProgression,
                "Insufficient token liquidity for new epoch"
            );

            // Increment to next epoch since cooldown period has passed
            currentTokenEpochs[token]++;
            pool = tokenPools[token][currentTokenEpochs[token]]; // Get the new epoch pool
        }

        if (pool.uniswapPair == address(0)) {
            pool.uniswapPair = getPairAddress(token);
        }
        require(pool.uniswapPair != address(0), "Pair does not exist");

        TokenProvider storage provider = tokenProviders[token][msg.sender][
            currentTokenEpochs[token]
        ];

        // Add user to participated epochs
        _addUserToParticipatedEpochs(
            token,
            msg.sender,
            currentTokenEpochs[token],
            false
        );

        // Calculate pending token rewards before update
        if (provider.lpShares > 0) {
            uint256 pendingTokens = (provider.lpShares *
                pool.accRewardPerShare) /
                SCALE -
                provider.rewardDebt;
            provider.pendingReward += pendingTokens;

            // Calculate pending ETH rewards before update
            uint256 pendingEth = (provider.lpShares *
                pool.accETHRewardPerShare) /
                SCALE -
                provider.ethRewardDebt;
            provider.pendingETHReward += pendingEth;
        }

        // Calculate LP shares to mint
        uint256 lpSharesToMint = _calculateLPShares(
            tokenAmount,
            pool.accountedToken,
            pool.totalLPShares
        );

        provider.lpShares += lpSharesToMint;
        provider.tokenAmount += tokenAmount;
        provider.rewardDebt =
            (provider.lpShares * pool.accRewardPerShare) /
            SCALE;
        provider.ethRewardDebt =
            (provider.lpShares * pool.accETHRewardPerShare) /
            SCALE;

        pool.totalTokens += tokenAmount;
        pool.accountedToken += tokenAmount;
        pool.totalLPShares += lpSharesToMint;

        // Track total tokens added by LPs
        totalTokensAdded[token] += tokenAmount;

        // Transfer tokens from user
        IERC20(token).safeTransferFrom(msg.sender, address(this), tokenAmount);

        emit TokenLiquidityDeposited(
            msg.sender,
            token,
            tokenAmount,
            lpSharesToMint
        );
    }

    /**
     * @notice Remove all liquidity from the pool by providing epochs, shares and min amounts
     * @param token Address of the token to withdraw from
     * @param ethEpochs Epochs to remove liquidity from
     * @param tokenEpochs Epochs to remove liquidity from
     * @param ethShares Percentages of pool to withdraw (in basis points, 10000 = 100%)
     * @param tokenShares Percentages of pool to withdraw (in basis points, 10000 = 100%)
     * @param minEthAmounts Minimum amounts of ETH to receive
     * @param minTokenAmounts Minimum amounts of tokens to receive
     */
    function removeAllEpochsLiquidity(
        address token,
        uint256[] memory ethEpochs,
        uint256[] memory tokenEpochs,
        uint256[] memory ethShares,
        uint256[] memory tokenShares,
        uint256[] memory minEthAmounts,
        uint256[] memory minTokenAmounts
    ) external isNotBlocked(token) nonReentrant {
        require(token != address(0), "Invalid token address");
        require(
            ethEpochs.length == ethShares.length &&
                ethEpochs.length == minEthAmounts.length,
            "Invalid ETH epochs length"
        );
        require(
            tokenEpochs.length == tokenShares.length &&
                tokenEpochs.length == minTokenAmounts.length,
            "Invalid token epochs length"
        );

        uint256 totalItems = ethEpochs.length + tokenEpochs.length;
        require(totalItems <= MAX_BATCH_SIZE, "Batch size too large");

        // Check gas limit
        uint256 estimatedGas = totalItems * GAS_LIMIT_PER_ITEM + GAS_BUFFER;
        require(
            gasleft() >= estimatedGas,
            "Insufficient gas for batch operation"
        );

        // Process ETH epochs
        for (uint256 i = 0; i < ethEpochs.length; i++) {
            require(
                ethShares[i] > 0 && ethShares[i] <= 10000,
                "Invalid shares percentage"
            );
            require(ethEpochs[i] <= currentETHEpochs[token], "Invalid epoch");
            _removeETHLiquidity(
                token,
                ethShares[i],
                minEthAmounts[i],
                ethEpochs[i]
            );
        }

        for (uint256 i = 0; i < tokenEpochs.length; i++) {
            require(
                tokenShares[i] > 0 && tokenShares[i] <= 10000,
                "Invalid shares percentage"
            );
            require(
                tokenEpochs[i] <= currentTokenEpochs[token],
                "Invalid epoch"
            );
            _removeTokenLiquidity(
                token,
                tokenShares[i],
                minTokenAmounts[i],
                tokenEpochs[i]
            );
        }

        emit BatchRemovalCompleted(msg.sender, token, totalItems);
    }

    /**
